CREATE TABLE "Orders_fact" (
  "order_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" varchar NOT NULL,
  "date_key" int,
  "time_key" int,
  "store_key" int,
  "employee_key" int,
  "customer_key" int,
  "subtotal" decimal,
  "discount_total" decimal,
  "tax" decimal,
  "tip" decimal,
  "order_channel" varchar,
  "payment_method" varchar
);

CREATE TABLE "fact_sales" (
  "sales_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_item_id" varchar NOT NULL,
  "order_id" varchar NOT NULL,
  "date_key" int,
  "time_key" int,
  "store_key" int,
  "product_key" int,
  "employee_key" int,
  "customer_key" int,
  "quantity" int,
  "unit_price" decimal,
  "gross_sales" decimal,
  "item_discount" decimal,
  "net_sales" decimal,
  "promo_code" varchar
);

CREATE TABLE "fact_loyalty_transactions" (
  "loyalty_txn_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "loyalty_txn_id" varchar NOT NULL,
  "customer_key" int,
  "customer_tier_key" int,
  "date_key" int,
  "order_id" varchar,
  "txn_type" varchar,
  "points" int
);

CREATE TABLE "fact_employee_shifts" (
  "shift_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shift_id" int NOT NULL,
  "employee_key" int,
  "store_key" int,
  "date_key" int,
  "time_key" int,
  "shift_start" timestamp,
  "shift_end" timestamp,
  "hourly_rate_at_shift" decimal
);

CREATE TABLE "fact_inventory_waste" (
  "waste_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "waste_id" varchar NOT NULL,
  "date_key" int,
  "store_key" int,
  "ingredient_key" int,
  "quantity_wasted" decimal,
  "waste_reason" varchar
);

CREATE TABLE "fact_ingredient_cost_history" (
  "ingredient_cost_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ingredient_key" int,
  "effective_date" date,
  "end_date" date,
  "unit_cost" decimal
);

CREATE TABLE "fact_product_price_history" (
  "product_price_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_key" int,
  "effective_date" date,
  "end_date" date,
  "base_price" decimal
);

CREATE TABLE "fact_inventory_snapshot" (
  "snapshot_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "date_key" int,
  "store_key" int,
  "ingredient_key" int,
  "quantity_on_hand" decimal,
  "reorder_threshold" decimal
);

CREATE TABLE "dim_employee" (
  "employee_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "employee_id" varchar NOT NULL,
  "first_name" varchar,
  "last_name" varchar,
  "hire_date" date,
  "termination_date" date,
  "role" varchar,
  "home_store_id" varchar,
  "hourly_rate" decimal
);

CREATE TABLE "dim_store" (
  "store_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "store_id" varchar NOT NULL,
  "store_name" varchar,
  "city" varchar,
  "state" varchar,
  "zip" varchar,
  "region" varchar,
  "open_date" date,
  "square_footage" int,
  "has_drive_thru" boolean
);

CREATE TABLE "dim_date" (
  "date_key" int PRIMARY KEY,
  "full_date" date,
  "day" int,
  "day_name" varchar,
  "week_number" int,
  "month" int,
  "month_name" varchar,
  "quarter" int,
  "year" int,
  "is_weekend" boolean
);

CREATE TABLE "dim_time" (
  "time_key" int PRIMARY KEY,
  "full_time" time,
  "hour" int,
  "minute" int,
  "am_pm" varchar,
  "day_period" varchar
);

CREATE TABLE "dim_customer" (
  "customer_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" varchar,
  "first_name" varchar,
  "last_name" varchar,
  "signup_date" date,
  "signup_store_id" varchar,
  "current_tier" varchar,
  "is_guest" boolean
);

CREATE TABLE "dim_product" (
  "product_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" varchar NOT NULL,
  "product_name" varchar,
  "category" varchar,
  "subcategory" varchar,
  "is_seasonal" boolean,
  "launch_date" date,
  "discontinued_date" date
);

CREATE TABLE "dim_ingredient" (
  "ingredient_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ingredient_id" varchar NOT NULL,
  "ingredient_name" varchar,
  "ingredient_type" varchar,
  "unit_of_measure" varchar,
  "supplier_id" varchar,
  "unit_cost" decimal
);

CREATE TABLE "dim_customer_tier" (
  "customer_tier_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" varchar NOT NULL,
  "tier" varchar,
  "effective_date" date,
  "end_date" date
);

CREATE TABLE "employee_rate_history" (
  "employee_rate_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "employee_id" varchar,
  "hourly_rate" decimal,
  "effective_date" date,
  "end_date" date
);

CREATE TABLE "recipes" (
  "recipe_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_key" int,
  "ingredient_key" int,
  "size" varchar,
  "quantity_used" decimal,
  "unit_of_measure" varchar
);

CREATE TABLE "promo_codes" (
  "promotion_key" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "promo_code" varchar NOT NULL,
  "description" varchar,
  "discount_type" varchar,
  "discount_value" decimal,
  "start_date" date,
  "end_date" date
);

